    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 4-year-old boy presents with a painless limp that has worsened over several weeks. He occasionally complains of vague left knee and thigh pain. He is afebrile and has limited internal rotation and abduction of the left hip. Radiographs show increased density and a subchondral crescent sign in the femoral head. What is the most likely diagnosis?', '["Transient synovitis", "Slipped capital femoral epiphysis", "Developmental dysplasia of the hip", "Legg-Calv\u00e9-Perthes disease", "Septic arthritis"]'::jsonb, 3, 'Legg-Calvé-Perthes disease is idiopathic avascular necrosis of the femoral head, classically seen in boys aged 4-8. It often presents insidiously with a painless limp or referred pain to the thigh/knee. Radiographs progress from sclerosis to fragmentation and reossification. The crescent sign represents a subchondral fracture.'),
    (v_topic_id, 'A 5-month-old male infant is diagnosed with Developmental Dysplasia of the Hip (DDH) via ultrasound. The hip is reducible. What is the standard first-line treatment for this patient?', '["Observation only", "Pavlik harness", "Closed reduction and spica casting", "Open reduction and pelvic osteotomy", "Triple diapering"]'::jsonb, 1, 'For infants < 6 months of age with a reducible dysplastic or dislocated hip, the Pavlik harness is the gold standard treatment. It maintains the hip in flexion and abduction, promoting concentric reduction and acetabular remodeling. Closed reduction is typically reserved for failures or children 6-18 months.'),
    (v_topic_id, 'A 8-year-old boy presents with a painless limp that has worsened over several weeks. He occasionally complains of vague right knee and thigh pain. He is afebrile and has limited internal rotation and abduction of the right hip. Radiographs show increased density and a subchondral crescent sign in the femoral head. What is the most likely diagnosis?', '["Legg-Calv\u00e9-Perthes disease", "Septic arthritis", "Developmental dysplasia of the hip", "Transient synovitis", "Slipped capital femoral epiphysis"]'::jsonb, 0, 'Legg-Calvé-Perthes disease is idiopathic avascular necrosis of the femoral head, classically seen in boys aged 4-8. It often presents insidiously with a painless limp or referred pain to the thigh/knee. Radiographs progress from sclerosis to fragmentation and reossification. The crescent sign represents a subchondral fracture.'),
    (v_topic_id, 'Patient #65213: An 15-year-old overweight adolescent undergoes in situ pinning for a stable Slipped Capital Femoral Epiphysis (SCFE). At follow-up, the patient complains of severe stiffness and loss of joint space is noted on X-ray. What is this devastating complication?', '["Infection", "Nonunion", "Chondrolysis", "Avascular necrosis of the femoral head", "Heterotopic ossification"]'::jsonb, 2, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 10-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Varus", "Supination", "Adductus", "Equinus", "Cavus"]'::jsonb, 3, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 15-year-old volleyball player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Activity modification, ice, NSAIDs, and reassurance", "Intra-articular corticosteroid injection", "Surgical excision of the ossicle", "Immobilization in a long leg cast for 6 weeks", "Strict non-weight bearing with crutches"]'::jsonb, 0, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'Patient #14982: A 7-month-old infant is referred to orthopedics for asymmetric gluteal folds and a leg length discrepancy. Which imaging modality is considered the gold standard to evaluate for Developmental Dysplasia of the Hip (DDH) at this specific age?', '["CT scan", "Ultrasound of the hips", "Bone scan", "MRI of the pelvis", "AP radiograph of the pelvis"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'Patient #43250: A 6-year-old child presents with a limp that started yesterday morning. Two weeks ago, he had a mild URI. He is well-appearing. He refuses to bear weight fully but has only mild pain with passive hip ROM. Labs show a normal WBC count and an ESR of 15 mm/hr. What is the most likely diagnosis?', '["Slipped capital femoral epiphysis", "Transient synovitis", "Juvenile idiopathic arthritis", "Septic arthritis", "Legg-Calv\u00e9-Perthes disease"]'::jsonb, 1, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 12-year-old track player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Surgical excision of the ossicle", "Strict non-weight bearing with crutches", "Intra-articular corticosteroid injection", "Activity modification, ice, NSAIDs, and reassurance", "Immobilization in a long leg cast for 6 weeks"]'::jsonb, 3, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'A 14-year-old track player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Surgical excision of the ossicle", "Intra-articular corticosteroid injection", "Strict non-weight bearing with crutches", "Activity modification, ice, NSAIDs, and reassurance", "Immobilization in a long leg cast for 6 weeks"]'::jsonb, 3, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'A 13-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the bilateral. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["CT scan of the pelvis", "AP radiograph of the pelvis", "MRI of the hips", "Ultrasound of the hips", "Bone scan"]'::jsonb, 3, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 5-year-old child refuses to bear weight on the right leg. The hip is held in flexion, abduction, and external rotation. Temperature is 39.5°C. Laboratory evaluation shows a WBC count of 15,000/mm³ and an ESR of 50 mm/hr. According to the Kocher criteria, what is the probability that this child has septic arthritis rather than transient synovitis?', '["> 90% (Very high probability)", "About 25%", "Exactly 0%", "About 50%", "< 10% (Very low probability)"]'::jsonb, 0, 'The Kocher criteria differentiate septic arthritis from transient synovitis. The 4 criteria are: non-weight-bearing, fever > 38.5°C, ESR > 40 mm/hr, and WBC > 12,000/mm³. Having all 4 predictors yields a 99% probability of septic arthritis; 3 predictors yield a 93% probability. This child has 4 predictors.'),
    (v_topic_id, 'Patient #11386: A 3-year-old child, who is at the 95th percentile for weight, presents with progressively worsening bowing of the left leg (genu varum). Radiographs show a prominent ''beak'' at the medial metaphysis of the proximal tibia. What is the diagnosis?', '["Physiologic genu varum", "Rickets", "Achondroplasia", "Osgood-Schlatter disease", "Infantile Blount disease"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 4-year-old child refuses to bear weight on the right leg. The hip is held in flexion, abduction, and external rotation. Temperature is 39.0°C. Laboratory evaluation shows a WBC count of 15,000/mm³ and an ESR of 50 mm/hr. According to the Kocher criteria, what is the probability that this child has septic arthritis rather than transient synovitis?', '["Exactly 0%", "About 25%", "> 90% (Very high probability)", "< 10% (Very low probability)", "About 50%"]'::jsonb, 2, 'The Kocher criteria differentiate septic arthritis from transient synovitis. The 4 criteria are: non-weight-bearing, fever > 38.5°C, ESR > 40 mm/hr, and WBC > 12,000/mm³. Having all 4 predictors yields a 99% probability of septic arthritis; 3 predictors yield a 93% probability. This child has 4 predictors.'),
    (v_topic_id, 'Patient #1917: A 5-year-old child presents with a limp that started yesterday morning. Two weeks ago, he had a mild URI. He is well-appearing. He refuses to bear weight fully but has only mild pain with passive hip ROM. Labs show a normal WBC count and an ESR of 15 mm/hr. What is the most likely diagnosis?', '["Legg-Calv\u00e9-Perthes disease", "Juvenile idiopathic arthritis", "Transient synovitis", "Septic arthritis", "Slipped capital femoral epiphysis"]'::jsonb, 2, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 19-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Supination", "Cavus", "Varus", "Adductus", "Equinus"]'::jsonb, 4, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'Patient #73788: A 14-year-old boy presents with frequent ankle sprains and a painful, rigid flatfoot. Examination reveals severe restriction of subtalar motion and spasm of the peroneal muscles. Radiographs show a ''C-sign'' on the lateral view. What is the most likely diagnosis?', '["Calcaneonavicular coalition", "Flexible pes planus", "Posterior tibial tendon insufficiency", "Talocalcaneal coalition", "Sever disease"]'::jsonb, 3, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 10-year-old overweight male presents with left groin and knee pain. He walks with a limp. On examination, when his left hip is passively flexed, it obligatorily goes into external rotation. Radiographs show a posterior and inferior displacement of the proximal femoral epiphysis. What is the most appropriate management?', '["Open reduction and internal fixation", "Physical therapy and weight loss", "Pavlik harness", "Immediate non-weight bearing and in situ percutaneous pinning", "Closed reduction and spica casting"]'::jsonb, 3, 'Slipped Capital Femoral Epiphysis (SCFE) occurs typically in overweight adolescents. The hallmark physical exam finding is obligatory external rotation with hip flexion. Treatment is strictly in situ pinning (without attempts at forceful closed reduction, which increases the risk of avascular necrosis) to stabilize the physis.'),
    (v_topic_id, 'A 13-day-old infant is brought to the clinic for bilateral clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Supination", "Equinus", "Adductus", "Varus", "Cavus"]'::jsonb, 1, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 4-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the right. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["Bone scan", "Ultrasound of the hips", "AP radiograph of the pelvis", "CT scan of the pelvis", "MRI of the hips"]'::jsonb, 1, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 13-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the right. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["MRI of the hips", "CT scan of the pelvis", "AP radiograph of the pelvis", "Bone scan", "Ultrasound of the hips"]'::jsonb, 4, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 10-year-old soccer player presents with posterior heel pain. The pain worsens after running and improves with rest. Examination reveals tenderness upon medial-lateral compression of the calcaneal tuberosity (positive ''squeeze test''). There is tightness of the Achilles tendon. What is the most likely diagnosis?', '["Achilles tendon rupture", "Plantar fasciitis", "Tarsal coalition", "Calcaneal stress fracture", "Calcaneal apophysitis (Sever disease)"]'::jsonb, 4, 'Sever disease is a traction apophysitis of the calcaneus where the Achilles tendon inserts. It is a common cause of heel pain in athletic children aged 8-12. The classic exam finding is pain with medial/lateral compression of the heel. Treatment includes heel cups, calf stretching, and NSAIDs.'),
    (v_topic_id, 'A 10-year-old falls from a swing and sustains a significantly displaced extension-type supracondylar humerus fracture. Upon examination, the child is unable to make an ''OK'' sign (unable to flex the IP joint of the thumb and DIP joint of the index finger). Which nerve is most likely injured?', '["Musculocutaneous nerve", "Axillary nerve", "Ulnar nerve", "Radial nerve", "Anterior interosseous nerve (AIN)"]'::jsonb, 4, 'The anterior interosseous nerve (AIN), a branch of the median nerve, is the most commonly injured nerve in extension-type supracondylar humerus fractures. Injury manifests as an inability to flex the IP joint of the thumb (flexor pollicis longus) and the DIP of the index finger (flexor digitorum profundus), resulting in an inability to make the ''''A-OK'''' sign.'),
    (v_topic_id, 'A 4-year-old child refuses to bear weight on the right leg. The hip is held in flexion, abduction, and external rotation. Temperature is 38.6°C. Laboratory evaluation shows a WBC count of 15,000/mm³ and an ESR of 50 mm/hr. According to the Kocher criteria, what is the probability that this child has septic arthritis rather than transient synovitis?', '["< 10% (Very low probability)", "About 50%", "> 90% (Very high probability)", "Exactly 0%", "About 25%"]'::jsonb, 2, 'The Kocher criteria differentiate septic arthritis from transient synovitis. The 4 criteria are: non-weight-bearing, fever > 38.5°C, ESR > 40 mm/hr, and WBC > 12,000/mm³. Having all 4 predictors yields a 99% probability of septic arthritis; 3 predictors yield a 93% probability. This child has 4 predictors.'),
    (v_topic_id, 'A 11-day-old infant is brought to the clinic for unilateral right clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Equinus", "Supination", "Cavus", "Adductus", "Varus"]'::jsonb, 0, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
